import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { parsePilotFrontmatter, pilotSlugify } from '../src/pilot';
// The independent port, which the frontmatter round-trip tests use. It must agree with Python too.
import { parsePilotFrontmatter as parsePilotPort, pilotSlugify as pilotSlugifyPort } from './pilot-parser';

// Expectations generated by running the pilot's own `slugify` and `parse_frontmatter` with Python 3
// (packages/changes/scripts/pilot-expectations.py). They are the oracle: the cases are characters
// Python and JavaScript classify differently (U+0085, U+001C–U+001F, U+2028, U+00A0, U+3000, U+FEFF).
interface Fixture {
  source: { repository: string; file: string; commit: string };
  slugify: { title: string; slug: string }[];
  frontmatter: { text: string; meta: Record<string, string | string[]>; body: string }[];
}

const fixture = JSON.parse(readFileSync(new URL('./fixtures/pilot/python-expectations.json', import.meta.url), 'utf8')) as Fixture;

describe('pilot Python semantics', () => {
  it('records which pilot commit the expectations came from', () => {
    expect(fixture.source).toMatchObject({
      repository: 'TimChr78/martechsignal',
      file: 'tools/build_blog.py',
      commit: 'b1b0bd3295f693944b8d7f783f2ab1712dd3eda0',
    });
  });

  it('slugifies exactly like the pilot for characters Python and JavaScript classify differently', () => {
    for (const { title, slug } of fixture.slugify) {
      expect(pilotSlugify(title), JSON.stringify(title)).toBe(slug);
      // The test port must agree with Python as well, because the frontmatter tests depend on it.
      expect(pilotSlugifyPort(title), JSON.stringify(title)).toBe(slug);
    }
  });

  it('slugs a line separator as whitespace and keeps U+FEFF out of the slug', () => {
    // The reviewer's case: Python's `\s` covers U+0085 and U+2028, JavaScript's does not, and
    // JavaScript's `\s` covers U+FEFF, which Python's does not.
    expect(pilotSlugify('Hello\u0085World')).toBe('hello-world');
    expect(pilotSlugify('Hello\u2028World')).toBe('hello-world');
    expect(pilotSlugify('Hello\ufeffWorld')).toBe('helloworld');
  });

  it('parses frontmatter exactly like the pilot', () => {
    for (const { text, meta, body } of fixture.frontmatter) {
      expect(parsePilotFrontmatter(text), JSON.stringify(text)).toEqual({ meta, body });
      expect(parsePilotPort(text), JSON.stringify(text)).toEqual({ meta, body });
    }
  });

  it('keeps a value whole across a line separator, as Python’s "." does', () => {
    // The reviewer's second case: Python's `(.+)` stops only at `\n`, so a U+2028 inside a value is
    // part of it; a JavaScript `.+` would truncate the value there.
    const { meta } = parsePilotFrontmatter('---\ntitle: Hello\u2028World\n---\n');
    expect(meta.title).toBe('Hello\u2028World');
    expect(parsePilotFrontmatter('---\ntitle: A\u2029B\n---\n').meta.title).toBe('A\u2029B');
  });

  it('strips Python’s whitespace, not JavaScript’s, around a value', () => {
    // U+0085 is whitespace to Python and stripped; U+FEFF is whitespace to JavaScript and kept.
    expect(parsePilotFrontmatter('---\ntitle: \u0085Hello\n---\n').meta.title).toBe('Hello');
    expect(parsePilotFrontmatter('---\ntitle: \ufeffHello\n---\n').meta.title).toBe('\ufeffHello');
  });
});
